package io.github.diodeme.ji.relay;

import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.time.Clock;
import java.time.Duration;
import java.util.Base64;
import java.util.HexFormat;
import java.util.Optional;
import java.util.Set;
import java.util.UUID;

/** Two-level Relay Owner bootstrap and trusted-device invitation state machine. */
public final class RelayPairingService {
    private static final Duration MATERIAL_TTL = Duration.ofMinutes(10);
    private final RelayMetadataStore store;
    private final Clock clock;
    private final SecureRandom random;
    private Bootstrap bootstrap;

    public RelayPairingService(RelayMetadataStore store, Clock clock, SecureRandom random) {
        this.store = java.util.Objects.requireNonNull(store, "store");
        this.clock = java.util.Objects.requireNonNull(clock, "clock");
        this.random = java.util.Objects.requireNonNull(random, "random");
    }

    public synchronized BootstrapMaterial issueOwnerBootstrap(String tenantId) {
        if (!store.devices(tenantId).isEmpty()) throw new IllegalStateException("Relay Owner already exists");
        byte[] secret = secret();
        String pin = String.format(java.util.Locale.ROOT, "%08d", random.nextInt(100_000_000));
        bootstrap = new Bootstrap(tenantId, digest(secret, pin), clock.instant().plus(MATERIAL_TTL));
        return new BootstrapMaterial(pin, Base64.getUrlEncoder().withoutPadding().encodeToString(secret),
                bootstrap.expiresAt());
    }

    public synchronized RelayMetadataStore.Device claimOwner(
            String tenantId, String pin, String secret, String deviceId, byte[] publicKey) {
        Bootstrap value = bootstrap;
        byte[] suppliedSecret = decodeSecret(secret);
        if (value == null || !value.tenantId().equals(tenantId) || !clock.instant().isBefore(value.expiresAt())
                || !MessageDigest.isEqual(value.proof(), digest(suppliedSecret, pin))
                || !store.devices(tenantId).isEmpty()) {
            throw new SecurityException("Relay Owner bootstrap rejected");
        }
        bootstrap = null;
        var device = new RelayMetadataStore.Device(tenantId, deviceId, publicKey,
                Set.of(RelayRole.RELAY_OWNER), clock.instant(), Optional.empty());
        store.saveDevice(device);
        return device;
    }

    public InvitationMaterial invite(String tenantId, String issuerDeviceId, Set<String> hostIds) {
        requireOwner(tenantId, issuerDeviceId);
        byte[] secret = secret();
        String invitationId = UUID.randomUUID().toString();
        String fingerprint = fingerprint(secret, invitationId);
        var invitation = new RelayMetadataStore.Invitation(tenantId, invitationId, issuerDeviceId, hostIds,
                digest(secret), fingerprint, clock.instant().plus(MATERIAL_TTL), Optional.empty(), Optional.empty());
        store.saveInvitation(invitation);
        return new InvitationMaterial(invitationId,
                Base64.getUrlEncoder().withoutPadding().encodeToString(secret), fingerprint,
                invitation.expiresAt(), hostIds);
    }

    public boolean confirm(String tenantId, String invitationId, String ownerDeviceId, String fingerprint) {
        requireOwner(tenantId, ownerDeviceId);
        RelayMetadataStore.Invitation invitation = store.invitation(tenantId, invitationId).orElse(null);
        return invitation != null && MessageDigest.isEqual(
                invitation.fingerprint().getBytes(StandardCharsets.US_ASCII),
                fingerprint.getBytes(StandardCharsets.US_ASCII))
                && store.confirmInvitation(tenantId, invitationId, ownerDeviceId, clock.instant());
    }

    public RelayMetadataStore.Device accept(
            String tenantId, String invitationId, String secret, String deviceId, byte[] publicKey) {
        RelayMetadataStore.Invitation invitation = store.invitation(tenantId, invitationId).orElseThrow(
                () -> new SecurityException("invitation rejected"));
        if (!MessageDigest.isEqual(invitation.secretHash(), digest(decodeSecret(secret)))
                || !store.consumeInvitation(tenantId, invitationId, deviceId, publicKey, clock.instant())) {
            throw new SecurityException("invitation rejected");
        }
        var device = new RelayMetadataStore.Device(tenantId, deviceId, publicKey,
                Set.of(RelayRole.RELAY_OWNER), clock.instant(), Optional.empty());
        store.saveDevice(device);
        invitation.hostIds().forEach(hostId -> store.saveGrant(new RelayMetadataStore.Grant(
                tenantId, hostId, deviceId, Set.of("host:request"), clock.instant())));
        return device;
    }

    private void requireOwner(String tenantId, String deviceId) {
        RelayMetadataStore.Device device = store.device(tenantId, deviceId).orElseThrow(
                () -> new SecurityException("Relay Owner required"));
        if (!device.active() || !device.roles().contains(RelayRole.RELAY_OWNER)) {
            throw new SecurityException("Relay Owner required");
        }
    }

    private byte[] secret() {
        byte[] value = new byte[32];
        random.nextBytes(value);
        return value;
    }

    private static byte[] decodeSecret(String value) {
        try {
            byte[] decoded = Base64.getUrlDecoder().decode(value);
            if (decoded.length != 32) throw new IllegalArgumentException("wrong length");
            return decoded;
        } catch (IllegalArgumentException failure) {
            throw new SecurityException("pairing material rejected", failure);
        }
    }

    private static byte[] digest(byte[]... values) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            for (byte[] value : values) digest.update(value);
            return digest.digest();
        } catch (java.security.NoSuchAlgorithmException impossible) {
            throw new IllegalStateException(impossible);
        }
    }

    private static byte[] digest(byte[] secret, String pin) {
        return digest(secret, pin.getBytes(StandardCharsets.US_ASCII));
    }

    private static String fingerprint(byte[] secret, String invitationId) {
        byte[] hash = digest(secret, invitationId.getBytes(StandardCharsets.UTF_8));
        ByteBuffer value = ByteBuffer.wrap(hash);
        return HexFormat.ofDelimiter("-").formatHex(ByteBuffer.allocate(6)
                .putShort(value.getShort()).putShort(value.getShort()).putShort(value.getShort()).array());
    }

    private record Bootstrap(String tenantId, byte[] proof, java.time.Instant expiresAt) {
        private Bootstrap { proof = proof.clone(); }
        @Override public byte[] proof() { return proof.clone(); }
    }

    public record BootstrapMaterial(String pin, String secret, java.time.Instant expiresAt) {}
    public record InvitationMaterial(String invitationId, String secret, String fingerprint,
                                     java.time.Instant expiresAt, Set<String> hostIds) {
        public InvitationMaterial { hostIds = Set.copyOf(hostIds); }
    }
}
